SELECT ROUTINE_SCHEMA, ROUTINE_NAME, SPECIFIC_NAME, ROUTINE_TYPE, FUNCTION_TYPE, MAX_DYNAMIC_RESULT_SETS FROM QSYS2.SYSROUTINES WHERE ROUTINE_SCHEMA IN ('QSYS2', 'SYSTOOLS') AND (ROUTINE_NAME IN ('ACTIVE_JOB_INFO','JOB_INFO','JOB_DESCRIPTION_INFO','JOBLOG_INFO','SUBSYSTEM_INFO','SUBSYSTEM_POOL_INFO','MEMORY_POOL','MEMORY_POOL_INFO','SYSTEM_STATUS','SYSTEM_STATUS_INFO','SYSTEM_STATUS_INFO_BASIC','SYSTEM_ACTIVITY_INFO','SYSTEM_VALUE_INFO','OBJECT_STATISTICS','OBJECT_LOCK_INFO','OBJECT_PRIVILEGES','OBJECT_OWNERSHIP','LIBRARY_INFO','LIBRARY_LIST_INFO','IFS_OBJECT_STATISTICS','IFS_READ','IFS_READ_BINARY','IFS_READ_UTF8','IFS_WRITE','IFS_WRITE_BINARY','IFS_WRITE_UTF8','IFS_OBJECT_PRIVILEGES','IFS_OBJECT_LOCK_INFO','USER_INFO','USER_INFO_BASIC','GROUP_PROFILE_ENTRIES','AUTHORIZATION_LIST_INFO','AUTHORIZATION_LIST_USER_INFO','FUNCTION_INFO','FUNCTION_USAGE','SECURITY_INFO','OUTPUT_QUEUE_INFO','OUTPUT_QUEUE_ENTRIES','OUTPUT_QUEUE_ENTRIES_BASIC','SPOOLED_FILE_DATA','SPOOLED_FILE_INFO','MESSAGE_QUEUE_INFO','HISTORY_LOG_INFO','MESSAGE_FILE_DATA','REPLY_LIST_INFO','SCHEDULED_JOB_INFO','JOB_QUEUE_INFO','JOB_QUEUE_ENTRIES','PTF_INFO','GROUP_PTF_INFO','GROUP_PTF_DETAILS','LICENSE_INFO','SOFTWARE_PRODUCT_INFO','NETSTAT_INFO','NETSTAT_JOB_INFO','NETSTAT_INTERFACE_INFO','NETSTAT_ROUTE_INFO','TCPIP_INFO','SERVER_SBS_ROUTING','DNS_LOOKUP','ASP_INFO','ASP_VARY_INFO','SYSDISKSTAT','DISK_UNIT_INFO','MEDIA_LIBRARY_INFO','JOURNAL_INFO','JOURNAL_RECEIVER_INFO','DISPLAY_JOURNAL','JOURNALED_OBJECTS','SYSLIMITS','SYSLIMTBL','ENVIRONMENT_VARIABLE_INFO','EXIT_POINT_INFO','EXIT_PROGRAM_INFO','USER_STORAGE','COLLECTION_SERVICES_INFO','HARDWARE_RESOURCE_INFO','ELECTRONIC_SERVICE_AGENT_INFO','BASE64_ENCODE','BASE64_DECODE','URL_ENCODE','URL_DECODE','SPLIT','GENERATE_SPREADSHEET','QCMDEXC','GENERATE_SQL','GENERATE_SQL_OBJECTS','SET_SERVER_SBS_ROUTING','OVERRIDE_QAQQINI','OVERRIDE_TABLE','SET_COLUMN_ATTRIBUTE','SET_PASE_SHELL_INFO','CHANGE_USER_PROFILE','LPRINTF','CHANGE_IFS_OWNER') OR ROUTINE_NAME LIKE 'AUDIT_JOURNAL%' OR ROUTINE_NAME LIKE 'HTTP%' OR ROUTINE_NAME LIKE 'NETSTAT%') ORDER BY ROUTINE_SCHEMA, ROUTINE_NAME, SPECIFIC_NAME;
