'QCMDEXC','GENERATE_SQL','GENERATE_SQL_OBJECTS','SET_SERVER_SBS_ROUTING','OVERRIDE_QAQQINI','OVERRIDE_TABLE','SET_COLUMN_ATTRIBUTE','SET_PASE_SHELL_INFO','CHANGE_USER_PROFILE','LPRINTF','CHANGE_IFS_OWNER') OR R.ROUTINE_NAME LIKE 'AUDIT_JOURNAL%' OR R.ROUTINE_NAME LIKE 'HTTP%' OR R.ROUTINE_NAME LIKE 'NETSTAT%') ORDER BY P.SPECIFIC_SCHEMA, P.SPECIFIC_NAME, P.ROW_TYPE, P.ORDINAL_POSITION;
